{"cards": [{"node_code": "N_ab4c059988c19da9", "definition": "研究道路车辆动力源、能量转换与传递系统的机械结构与控制，涵盖内燃机、电机、变速器及多能源耦合的动力总成集成技术。", "boundary": "聚焦于车辆驱动系统的核心机械部件及其协同工作，包括发动机本体、传动机构、电池/电机集成及混动控制策略。与底盘系统的区别在于本节点侧重能量产生与传递，而非车辆支撑、转向或制动；与通用机械的区别在于针对车辆特定工况（如启停、变速）的优化。", "includes": ["内燃机、电动机、发电机及其在车辆中的集成与匹配", "机械式、液力式、电控式变速器及传动轴系", "混合动力、增程式及纯电驱动系统的能量管理架构"], "excludes": ["车辆悬架、转向、制动等底盘机械系统（归入道路车辆底盘与行驶系统）", "车身结构、空调热管理或辅助机械装置（归入车身、热管理与车辆辅助机械）"], "sibling_distinctions": [{"other_code": "N_f0c8dc116991e942", "rule": "本节点收录动力源与传动系统；兄弟节点收录承载、转向、制动及行驶稳定性系统。"}, {"other_code": "N_b333b74461018e0e", "rule": "本节点收录驱动核心部件；兄弟节点收录车身结构、环境控制及非驱动辅助机械。"}], "cross_boundary_rule": "若研究发动机或电机的通用热力学/电磁原理且脱离车辆集成，可关联至“热流体与能源动力工程”或“电气工程”；若涉及车辆特有的动力匹配、换挡逻辑或整车能量流，主挂载至本节点。"}, {"node_code": "N_f0c8dc116991e942", "definition": "研究道路车辆底盘结构、行驶机构及操控安全系统，包括车架、悬架、转向、制动及轮胎-路面交互的机械设计与动力学分析。", "boundary": "聚焦于车辆与路面接触及内部支撑系统的机械性能，涵盖底盘架构、行驶平顺性、操纵稳定性及制动效能。与动力总成的区别在于本节点侧重车辆姿态控制与载荷传递，而非能量产生；与车身的区别在于本节点侧重功能性底盘部件，而非封闭空间结构。", "includes": ["车架、车桥、悬架、减振器及车轮轮胎系统", "机械式与电动助力转向系统及操纵稳定性研究", "液压/电子制动系统及车辆纵向动力学控制"], "excludes": ["发动机、变速器及驱动电机等动力源部件（归入发动机、变速器与动力总成）", "车身覆盖件、内饰结构及空调系统（归入车身、热管理与车辆辅助机械）"], "sibling_distinctions": [{"other_code": "N_ab4c059988c19da9", "rule": "本节点收录底盘与行驶系统；兄弟节点收录动力源与传动系统。"}, {"other_code": "N_b333b74461018e0e", "rule": "本节点收录功能性底盘机械；兄弟节点收录车身结构及辅助机械。"}], "cross_boundary_rule": "若研究轮胎材料或通用轴承理论，可关联至“工程材料”或“机械设计与基础零部件”；若涉及车辆特有的悬架调校、转向手感或制动协调，主挂载至本节点。"}, {"node_code": "N_b333b74461018e0e", "definition": "研究道路车辆车身结构、环境控制系统及非驱动辅助机械装置，涵盖车身轻量化、碰撞安全、空调热管理及座椅/门窗等辅助机构。", "boundary": "聚焦于车辆乘员空间的结构完整性、环境舒适性及辅助功能机械。与底盘的区别在于本节点侧重封闭空间及人机交互部件，而非行驶支撑；与动力总成的区别在于本节点不涉及能量驱动核心。包括车身骨架、覆盖件、HVAC系统及各类辅助机械。", "includes": ["车身结构、碰撞安全、轻量化设计及NVH特性", "汽车空调、暖风、通风及电池/发动机热管理系统", "座椅、车门、后视镜、雨刮等辅助机械装置"], "excludes": ["发动机、变速器等动力总成部件（归入发动机、变速器与动力总成）", "悬架、转向、制动等底盘行驶系统（归入道路车辆底盘与行驶系统）"], "sibling_distinctions": [{"other_code": "N_ab4c059988c19da9", "rule": "本节点收录车身及辅助机械；兄弟节点收录动力源与传动系统。"}, {"other_code": "N_f0c8dc116991e942", "rule": "本节点收录车身结构及环境控制；兄弟节点收录底盘行驶及操控系统。"}], "cross_boundary_rule": "若研究通用热交换器原理，可关联至“热流体与能源动力工程”；若涉及车辆特有的空调布局、车身碰撞吸能结构或辅助机械的人机工程，主挂载至本节点。"}]}
